class Gradebook:
    def __init__(self) -> None:
        # assignment name -> (weight, kind)
        self._assignments = {}
        # student -> {assignment name -> grade}
        self._grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError("kind must be 'homework' or 'quiz'")
        self._assignments[name] = (float(weight), kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise KeyError(f"Unknown assignment: {assignment}")
        if not (2.0 <= grade <= 5.0):
            raise ValueError("Grade must be between 2.0 and 5.0")
        self._grades.setdefault(student, {})[assignment] = float(grade)

    def average(self, student: str) -> float:
        if not self._assignments:
            return 0.0

        grades = self._grades.get(student, {})

        # Resolve grades per assignment; missing counts as 2.0
        resolved = {}
        for name in self._assignments:
            resolved[name] = grades.get(name, 2.0)

        # Identify quizzes
        quiz_names = [
            name for name, (_, kind) in self._assignments.items() if kind == "quiz"
        ]

        dropped = None
        if len(quiz_names) > 1:
            dropped = min(quiz_names, key=lambda n: resolved[n])

        total_weight = 0.0
        weighted_sum = 0.0
        for name, (weight, _kind) in self._assignments.items():
            if name == dropped:
                continue
            weighted_sum += weight * resolved[name]
            total_weight += weight

        if total_weight == 0.0:
            return 0.0
        return weighted_sum / total_weight
